    # ------------------------------------------------------------
    def make_sensor_cluster(self):
        """Small rounded sensors with probe lines plus electrode pins."""
        group = VGroup()

        sensor_positions = [(-0.4, 0.2), (0.35, 0.05), (-0.05, -0.35)]
        for dx, dy in sensor_positions:
            rect = Rectangle(
                width=0.55, height=0.35,
                fill_color=TEAL, fill_opacity=0.85,
                stroke_color=WHITE, stroke_width=1.5,
            ).shift(RIGHT * dx + UP * dy)
            probe = Line(
                rect.get_bottom() + DOWN * 0.02,
                rect.get_bottom() + DOWN * 0.22,
                color=WHITE, stroke_width=2,
            )
            group.add(VGroup(rect, probe))

        electrode_positions = [(-0.05, 0.5), (0.6, -0.15), (-0.45, -0.1)]
        for dx, dy in electrode_positions:
            pin = Line(ORIGIN, UP * 0.35, color=WHITE, stroke_width=4).shift(
                RIGHT * dx + UP * dy + DOWN * 0.15
            )
            tip = Dot(pin.get_end(), radius=0.04, color=WHITE)
            group.add(VGroup(pin, tip))

        group.scale_to_fit_height(0.75)
        return group

    def make_head_brain(self):
        """Side-view head silhouette with a brain icon inside."""
        head = Ellipse(
            width=1.1, height=1.3,
            fill_color=GREY_B, fill_opacity=0.35,
            stroke_color=WHITE, stroke_width=2,
        )
        brain = SVGMobject(
            ASSET_PATHS["brain"],
            color=PURPLE, fill_opacity=1, stroke_opacity=1,
        ).scale_to_fit_height(0.65).move_to(head.get_center() + LEFT * 0.05)

        neck = Rectangle(
            width=0.2, height=0.25,
            fill_color=GREY_B, fill_opacity=0.5,
            stroke_color=WHITE, stroke_width=1.5,
        ).next_to(head, DOWN, buff=0.0).shift(DOWN * 0.05)

        group = VGroup(head, brain, neck)
        group.scale_to_fit_height(0.85)
        return group